// Only fetch sports you actually configured AND that are currently in-season
const tracked = $('Config').first().json.SPORTS.split(',').map(s => s.trim());
const raw = $input.all().map(i => i.json);
const activeList = Array.isArray(raw[0]) ? raw[0] : raw;
const activeKeys = activeList.map(s => s.key);
const sportsToFetch = tracked.filter(s => activeKeys.includes(s));

if (sportsToFetch.length === 0) {
  throw new Error('None of the sports in Config.SPORTS are currently active/in-season. Check the sport keys against /v4/sports.');
}

return sportsToFetch.map(sport => ({ json: { sport } }));

// De-vig bookmaker odds into fair (implied) win probabilities, averaged across all bookmakers.
// This is the "does it ever fail" layer: a single bad/missing odds response becomes a
// clearly-flagged error item instead of crashing the run.
const raw = $input.all().map(i => i.json);
const first = raw[0];

if (first && first.error) {
  return [{ json: { sport: $('Loop Over Sports').first().json.sport, error: true, message: (first.error.message || JSON.stringify(first.error)) } }];
}

const events = Array.isArray(first) ? first : raw;
const results = [];

function avg(arr) { return arr.reduce((a, b) => a + b, 0) / arr.length; }

for (const event of events) {
  if (!event.bookmakers || !event.bookmakers.length) continue;
  const probsByTeam = {};
  const oddsByTeam = {};

  for (const bm of event.bookmakers) {
    const market = (bm.markets || []).find(m => m.key === 'h2h');
    if (!market) continue;
    const overround = market.outcomes.reduce((sum, o) => sum + 1 / o.price, 0);
    for (const outcome of market.outcomes) {
      const fairProb = (1 / outcome.price) / overround;
      (probsByTeam[outcome.name] ||= []).push(fairProb);
      (oddsByTeam[outcome.name] ||= []).push(outcome.price);
    }
  }

  const implied = Object.keys(probsByTeam).map(team => ({
    team,
    implied_probability: Number(avg(probsByTeam[team]).toFixed(4)),
    avg_decimal_odds: Number(avg(oddsByTeam[team]).toFixed(3))
  })).sort((a, b) => b.implied_probability - a.implied_probability);

  if (!implied.length) continue;

  results.push({
    event_id: event.id,
    sport: event.sport_key,
    commence_time: event.commence_time,
    home_team: event.home_team,
    away_team: event.away_team,
    bookmaker_count: event.bookmakers.length,
    implied_probabilities: implied
  });
}

if (results.length === 0) {
  return [{ json: { sport: $('Loop Over Sports').first().json.sport, error: true, message: 'No events with usable h2h odds right now (off-season or no bookmakers listed yet).' } }];
}

return results.map(r => ({ json: r }));

const events = $('Compute Implied Probabilities').all().map(i => i.json);
const rawList = $input.all().map(i => i.json);

let usdToInr = 95.5;
try {
  const fx = $('Get FX Rate (USD to INR)').first().json;
  if (fx && fx.rates && fx.rates.INR) usdToInr = fx.rates.INR;
} catch (e) {
  usdToInr = 95.5;
}

return rawList.map((raw, idx) => {
  const event = events[idx] || events[0] || {};
  let llmResult;
  try {
    let candidate = (raw.result && raw.result.response) ? raw.result.response : (raw.response || null);
    if (!candidate && raw.result && raw.result.choices && raw.result.choices[0] && raw.result.choices[0].message) {
      candidate = raw.result.choices[0].message.content;
    }
    if (typeof candidate === 'object' && candidate !== null) {
      llmResult = candidate;
    } else if (typeof candidate === 'string') {
      const match = candidate.match(/\{[\s\S]*\}/);
      llmResult = match ? JSON.parse(match[0]) : JSON.parse(candidate);
    } else {
      const text = JSON.stringify(raw);
      const match = text.match(/\{[\s\S]*\}/);
      llmResult = match ? JSON.parse(match[0]) : null;
    }
    if (!llmResult || typeof llmResult.pick === 'undefined') throw new Error('missing pick field');
  } catch (e) {
    llmResult = { pick: 'no_bet', confidence: 0, reasoning: 'LLM output could not be parsed: ' + e.message, llm_parse_failed: true };
  }

  const pickedOdds = (event.implied_probabilities || []).find(p => p.team === llmResult.pick) || null;

  return {
    json: {
      event_id: event.event_id,
      sport: event.sport,
      home_team: event.home_team,
      away_team: event.away_team,
      commence_time: event.commence_time,
      bookmaker_count: event.bookmaker_count,
      market_implied_probabilities: event.implied_probabilities,
      llm_pick: llmResult.pick,
      llm_confidence: llmResult.confidence ?? null,
      llm_reasoning: llmResult.reasoning || '',
      llm_parse_failed: !!llmResult.llm_parse_failed,
      picked_avg_decimal_odds: pickedOdds ? pickedOdds.avg_decimal_odds : null,
      fx_usd_to_inr: usdToInr,
      generated_at: new Date().toISOString(),
      actual_result: null
    }
  };
});
